  RETURN NEW;
END;
$$;

-- ============================================================
-- FIX 8: update_channel_post_count trigger function missing SET search_path
-- ============================================================
-- Finding: SECURITY DEFINER with no SET search_path.
-- Severity: HIGH
-- Affected: update_channel_post_count trigger function

CREATE OR REPLACE FUNCTION public.update_channel_post_count()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status != 'approved' THEN
    UPDATE public.channels SET post_count = post_count + 1 WHERE id = NEW.channel_id;
  END IF;
  RETURN NEW;
END;
$$;

-- ============================================================
-- FIX 9: Comprehensive GRANT tightening — revoke PUBLIC/anon from all RPCs
-- ============================================================
-- Finding: Functions created without explicit GRANT default to PUBLIC (which
--   includes anon). Even though they have internal auth checks, belt-and-suspenders
--   demands revoking anon access at the GRANT level too.
-- Severity: HIGH
-- Affected: all public RPCs
-- Implementation: Dynamic loop checks pg_proc so missing functions are skipped
--   (idempotent — safe to re-run, works even if some RPCs don't exist yet).

DO $$
DECLARE
  fn_specs TEXT[] := ARRAY[
    'activate_approved_channels:0',
    'increment_channel_members:1',
    'handle_new_user:0',
    'handle_updated_at:0',
    'update_channel_post_count:0',
    'approve_channel_content:1',
    'reject_channel_content:2',
    'record_post_view:1',
    'admin_list_channel_activity:0',
    'admin_list_pending_content:0',
    'is_owner_or_admin:1',
    'can_post_to_channel:1',
    'export_my_data:0',
    'get_my_subscription_status:0',
    'get_my_channel_posts:1',
    'join_channel:1',
    'leave_channel:1',
    'update_channel:3',
    'delete_channel:1',
    'approve_post:1',
    'reject_post:2',
    'approve_subscription_request:1',
    'reject_subscription_request:2',
    'increment_storage_used:2',
    'decrement_storage_used:2'
  ];
  fn_spec TEXT;
  fn_name TEXT;
  fn_args INT;
  fn_oid OID;
  fn_sig TEXT;
BEGIN
  FOREACH fn_spec IN ARRAY fn_specs LOOP
    fn_name := split_part(fn_spec, ':', 1);
    fn_args := split_part(fn_spec, ':', 2)::INT;

    SELECT p.oid, pg_get_function_identity_arguments(p.oid)
      INTO fn_oid, fn_sig
      FROM pg_proc p
      JOIN pg_namespace n ON p.pronamespace = n.oid
     WHERE n.nspname = 'public'
       AND p.proname = fn_name
       AND p.pronargs = fn_args
     LIMIT 1;

    IF fn_oid IS NOT NULL THEN
      EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC', fn_name, fn_sig);
      EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM anon', fn_name, fn_sig);
      EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO authenticated', fn_name, fn_sig);
      RAISE NOTICE 'secured: %(%)', fn_name, fn_sig;
    ELSE
      RAISE NOTICE 'skipped (not found): % (args=%)', fn_name, fn_args;
    END IF;

    fn_oid := NULL;
    fn_sig := NULL;
  END LOOP;
END $$;

